var records=[{"app": "Light/Clean", "id": "project--empty", "frame": "FD1BB4B6-D067-44E4-B987-C2EEDAB2C5C3"}, {"app": "Light/Clean", "id": "project--work", "frame": "C53CA212-D8C8-4217-A94F-2D86BDE30EA4"}, {"app": "Dark/Clean", "id": "project--empty", "frame": "5ECE25B1-C637-4927-A0B5-F2D935480AD2"}, {"app": "Dark/Clean", "id": "project--work", "frame": "1078A02E-386C-4E16-B042-19C74F922CF2"}];records.forEach(e=>{var s=sketch.find('#'+e.frame,doc)[0];var b=s.layers.find(l=>l.name==='body');if(e.id==='project--empty'){var c=b.layers.find(l=>l.name==='link:new-conversation'&&l.type!=='SymbolInstance');if(c)c.remove();}else{var seg=b.layers.find(l=>l.name==='segmented-control');seg.layers.forEach(l=>l.style.fills=l.name==='link:project--work'?[{fillType:sketch.Style.FillType.Color,color:H.sw(e.app,'surface')}]:[]);}H.relayout(s);});H.out({fixed:records.length});